# Auto-generated by mosaic-emit-xaml in emit-project mode.
#
# Driver for the HelloDialog WinUI 3 host project. Regenerates the per-component
# triple from the Mosaic sources (if mosaic-compile is on PATH), then runs
# `dotnet build`.
#
# Known frictions:
#   - On a bare .NET SDK (no Visual Studio Build Tools), `dotnet build` will
#     end with one MSB4062 error about `Microsoft.Build.AppxPackage.RemovePayloadDuplicates`.
#     The .exe and dependencies are produced anyway; ignore the error.
#   - Without `<WindowsAppSDKSelfContained>true</WindowsAppSDKSelfContained>`,
#     a system-wide install of the Windows App Runtime is required:
#         winget install Microsoft.WindowsAppRuntime.1.7
#
param([switch]$Clean, [switch]$Run)

$proj = Join-Path $PSScriptRoot "HelloDialog.csproj"

if ($Clean) {
    Remove-Item -Recurse -Force -ErrorAction SilentlyContinue (Join-Path $PSScriptRoot "bin")
    Remove-Item -Recurse -Force -ErrorAction SilentlyContinue (Join-Path $PSScriptRoot "obj")
}

# The Platform=x64 arg is required because WindowsAppSDK's
# self-contained mode rejects AnyCPU. The csproj's <Platforms>x64</Platforms>
# only declares the SET of platforms; the ACTIVE one comes from this arg.
dotnet build $proj -c Debug -p:Platform=x64 --nologo
# `dotnet build` returns non-zero from the cosmetic MSB4062 even when the
# outputs ARE produced. Ignore $LASTEXITCODE for that one specific case.

if ($Run) {
    # x64 Debug bin path. .NET 9 puts the platform in the path
    # segment when -p:Platform=x64 is set.
    $exe = Join-Path $PSScriptRoot "bin\x64\Debug\net9.0-windows10.0.19041.0\win-x64\HelloDialog.exe"
    if (-not (Test-Path $exe)) {
        # Fallback to the non-platform-segment path for builds that
        # left it out.
        $exe = Join-Path $PSScriptRoot "bin\Debug\net9.0-windows10.0.19041.0\win-x64\HelloDialog.exe"
    }
    if (Test-Path $exe) {
        & $exe
    } else {
        Write-Host "No .exe at $exe -- build must have failed." -ForegroundColor Red
    }
}
